/* Feste Übersetzung der Lerninhalte (fa), maschinell erstellt, nicht von Muttersprachlern geprüft. Code bleibt unverändert. */
(function(r){"use strict";const f=r.SDAkademieFest=r.SDAkademieFest||{};(f["fa"]=f["fa"]||{})["arbeitsvertrag-rechte"]={"Wesentliche Arbeitsbedingungen herauslesen":"بیرون خواندن شرط‌های اصلی کار","Entgelt ist die Bezahlung für deine Arbeit. Du suchst im Vertrag nach Arbeit, Ort, Beginn, Bezahlung und Arbeitszeit.":"Entgelt (مزد) پرداخت برای کار شماست. شما در قرارداد دنبال کار، جا، شروع، پرداخت و ساعت کار می‌گردید.","Fehlende Angabe selbst einsetzen":"معلومات کم را خودتان نوشتن","Falsch: Die Wochenstunden ohne Abstimmung im Vertrag ergänzen. Richtig: Fehlende oder widersprüchliche Bedingungen beim Vertragspartner klären.":"اشتباه: ساعت‌های هفته را بدون هماهنگی در قرارداد اضافه کنید. درست: شرط‌های کم یا متناقض را با طرف قرارداد روشن کنید.","Form pauschal beurteilen":"شکل را کلی قضاوت کردن","Falsch: Aus einer allgemeinen Kursregel jede Vertragsform als wirksam oder unwirksam einstufen. Richtig: Die konkrete Formvorschrift und ihre Ausnahmen prüfen lassen.":"اشتباه: از یک قاعدهٔ عمومی کورس هر شکل قرارداد را معتبر یا نامعتبر بدانید. درست: بگذارید قاعدهٔ مشخص شکل و استثناهای آن بررسی شود.","Was ist bei Dario noch unklar?":"نزد داریو چه چیزی هنوز نامشخص است؟","Die Wochenstundenzahl.":"تعداد ساعت‌های هفته.","Der ausdrücklich genannte Arbeitsort.":"جای کار که صریحاً نام برده شده.","Der in den Unterlagen angegebene Beginn.":"شروعی که در اسناد نوشته شده.","Der Dialog bezeichnet ausdrücklich die fehlende klare Wochenstundenzahl.":"گفتگو صریحاً تعداد روشن ساعت‌های هفته را که کم است نام می‌برد.","Was ist ein sinnvoller nächster Schritt?":"یک قدم بعدی معقول چیست؟","Die Gesprächsangabe ohne Abstimmung selbst eintragen.":"معلومات گفتگو را بدون هماهنگی خودتان نوشتن.","Die Arbeitszeit mit dem Vertragspartner klären.":"ساعت کار را با طرف قرارداد روشن کردن.","Die fehlende Zahl aus einem allgemeinen Mustervertrag übernehmen.":"عدد کم را از یک قرارداد نمونهٔ عمومی گرفتن.","Eine Vertragsbedingung wird abgestimmt und nicht eigenmächtig ersetzt.":"یک شرط قرارداد هماهنگ می‌شود و خودسرانه عوض نمی‌شود.","Welche Aussage ist differenziert?":"کدام گفته سنجیده است؟","Ein zugänglicher elektronischer Text genügt unabhängig von Branche und Inhalt.":"یک متن الکترونیکی قابل دسترس بدون توجه به رشته و محتوا کافی است.","Eine Papierunterschrift belegt allein die Vollständigkeit aller Bedingungen.":"یک امضای کاغذی به تنهایی کامل بودن همهٔ شرط‌ها را ثابت می‌کند.","Form und Nachweispflichten müssen konkret geprüft werden.":"شکل و وظیفه‌های ثبت باید مشخص بررسی شوند.","Die gesetzlichen Vorgaben enthalten unterschiedliche Anforderungen und Ausnahmen.":"قاعده‌های قانونی خواسته‌ها و استثناهای مختلف دارند.","Markiere in einem fiktiven Vertrag nur tatsächlich genannte Bedingungen und stelle zu einer Lücke eine konkrete Rückfrage.":"در یک قرارداد ساختگی فقط شرط‌هایی را علامت بزنید که واقعاً نام برده شده‌اند و دربارهٔ یک کمبود یک سوال مشخص بپرسید.","Eine fehlende Bedingung bemerken":"متوجه شدن یک شرط کم","Dario: „Hier stehen Beginn und Arbeitsort, aber ich finde keine klare Wochenstundenzahl.“ Beraterin: „Dann markieren Sie die Stelle und fragen nach der vereinbarten Arbeitszeit.“ Dario: „Im Gespräch waren zwanzig Stunden genannt.“ Beraterin: „Halten Sie diese Abweichung fest und lassen Sie die Unterlagen klären, statt selbst eine Zahl einzutragen.“":"داریو: «اینجا شروع و جای کار نوشته شده، اما تعداد روشن ساعت‌های هفته را پیدا نمی‌کنم.» مشاور: «پس آن جا را علامت بزنید و دربارهٔ ساعت کار توافق‌شده بپرسید.» داریو: «در گفتگو بیست ساعت گفته شده بود.» مشاور: «این تفاوت را ثبت کنید و بگذارید اسناد روشن شوند، به جای اینکه خودتان یک عدد بنویسید.»","Vertrag und Nachweis unterscheiden":"جدا کردن قرارداد و ثبت","Der Arbeitsvertrag regelt die vereinbarte Arbeit. Ein Nachweis hält wichtige Bedingungen fest. § 2 NachwG nennt unter anderem Beginn, Ort, Tätigkeit, Entgelt und Arbeitszeit. Für Form und Fristen gelten einzelne Regeln und Ausnahmen. Eine kurze Nachricht enthält nicht automatisch alle nötigen Angaben. Umgekehrt ist nicht für jede Situation nur Papier zulässig.":"قرارداد کار کار توافق‌شده را تنظیم می‌کند. یک ثبت (Nachweis) شرط‌های مهم را نگه می‌دارد. § 2 NachwG از جمله شروع، جا، کار، مزد و ساعت کار را نام می‌برد. برای شکل و مهلت‌ها قاعده‌ها و استثناهای جداگانه اعتبار دارند. یک پیام کوتاه خودکار همهٔ معلومات لازم را ندارد. برعکس هم برای هر وضعیت فقط کاغذ مجاز نیست.","Vertragsbegriffe gezielt lesen":"خواندن هدفمند مفهوم‌های قرارداد","Prüfe, welche Arbeit du machen sollst und wo du eingesetzt wirst. Suche außerdem Beginn, Arbeitszeit und Bezahlung. Ein Tarifvertrag kann weitere Bedingungen regeln. Verweist dein Vertrag darauf, frage nach dem passenden Text. Markiere unklare Stellen. Notiere dazu eine konkrete Frage, statt die Bedeutung zu raten.":"بررسی کنید کدام کار را باید انجام دهید و کجا کار می‌کنید. علاوه بر آن شروع، ساعت کار و پرداخت را پیدا کنید. یک قرارداد جمعی (Tarifvertrag) می‌تواند شرط‌های بیشتری تنظیم کند. اگر قرارداد شما به آن اشاره می‌کند، متن مناسب را بخواهید. جاهای نامشخص را علامت بزنید. برای آن یک سوال مشخص یادداشت کنید، به جای اینکه معنا را حدس بزنید.","Mit offenen Fragen zur Klärung gehen":"رفتن با سوال‌های باز برای روشن‌سازی","Schreibe die unklare Stelle mit Seitenzahl auf. Notiere, was du dazu wissen möchtest. Ergänze keine Vertragsangabe im Namen des Betriebs. Frage, welche Fassung gelten soll. Widersprechen sich Gespräch und Text, lass das vor deiner Entscheidung klären. Bei einer rechtlichen Streitfrage brauchst du eine Prüfung deines konkreten Vertrags.":"جای نامشخص را با شمارهٔ صفحه بنویسید. یادداشت کنید که دربارهٔ آن چه می‌خواهید بدانید. هیچ معلومات قرارداد را به نام شرکت اضافه نکنید. بپرسید کدام نسخه باید اعتبار داشته باشد. اگر گفتگو و متن با هم تناقض دارند، بگذارید پیش از تصمیم شما روشن شود. در یک اختلاف حقوقی بررسی قرارداد مشخص خودتان لازم است.","Vertragsangaben ergänzen":"کامل کردن معلومات قرارداد","Setze „Arbeitszeit“ und „Arbeitsort“ ein.":"„Arbeitszeit“ (ساعت کار) و „Arbeitsort“ (جای کار) را بگذارید.","Ordne Zeitumfang und Ort getrennt zu.":"اندازهٔ وقت و جا را جدا وصل کنید.","Die Begriffe bezeichnen unterschiedliche wesentliche Bedingungen.":"این مفهوم‌ها شرط‌های اصلی مختلفی را نام می‌برند.","Die Wochenstunden betreffen die ___.":"Die Wochenstunden betreffen die ___. (ساعت‌های هفته به ___ مربوط‌اند.)","Die vereinbarte Einsatzstätte ist der ___.":"Die vereinbarte Einsatzstätte ist der ___. (جای کار توافق‌شده ___ است.)","Bedingungen zuordnen":"وصل کردن شرط‌ها","Verbinde die Angabe mit dem Begriff.":"معلومات را به مفهوم وصل کنید.","Eine Zeitdauer und ein Datum sind nicht dieselbe Bedingung.":"یک مدت و یک تاریخ یک شرط نیستند.","Die Zuordnung unterstützt systematisches Vertragslesen.":"این وصل کردن خواندن منظم قرارداد را حمایت می‌کند.","20 Wochenstunden":"20 ساعت در هفته","ab 1. Dezember":"از 1 دسامبر","monatliches Bruttoentgelt":"مزد ناخالص ماهانه","Die Lücke verstehen":"فهمیدن کمبود","Welche Angabe fehlt klar in Darios Unterlagen? Antworte mit einem Nomen.":"کدام معلومات در اسناد داریو روشن کم است؟ با یک اسم (به آلمانی) جواب دهید.","Gesucht ist die offene Bedingung.":"شرط باز پرسیده شده است.","Der Umfang der Arbeit muss noch geklärt werden.":"اندازهٔ کار هنوز باید روشن شود.","Eine Vertragsfrage formulieren":"نوشتن یک سوال قرارداد","Schreibe drei Sätze: Textbefund, frühere Gesprächsangabe und konkrete Bitte um Klärung.":"سه جمله بنویسید: یافتهٔ متن، معلومات قبلی گفتگو و خواهش مشخص برای روشن‌سازی.","Trenne den Inhalt des Dokuments von deiner Erinnerung an das Gespräch.":"محتوای سند را از خاطرهٔ خود از گفتگو جدا کنید.","Die Rückfrage zeigt den Widerspruch, ohne einen Vertrag selbst umzuschreiben.":"این سوال تناقض را نشان می‌دهد، بدون اینکه خودتان قرارداد را بازنویسی کنید.","Beschreibst du die tatsächlich fehlende Angabe?":"آیا معلومات واقعاً کم را توصیف می‌کنید؟","Kennzeichnest du zwanzig Stunden als Gesprächsangabe?":"آیا بیست ساعت را معلومات گفتگو مشخص می‌کنید؟","Bittest du um ausdrückliche Klärung?":"آیا روشن‌سازی صریح می‌خواهید؟","Verzichtest du auf eine eigenmächtige Vertragsergänzung?":"آیا از اضافه کردن خودسرانهٔ قرارداد پرهیز می‌کنید؟","Stand: November 2026. Allgemeine Information, keine Rechtsberatung. Prüfe aktuelle Regeln bei gesetze-im-internet.de.":"وضعیت: نوامبر 2026. معلومات عمومی، نه مشورهٔ حقوقی. قاعده‌های فعلی را در gesetze-im-internet.de بررسی کنید.","Nachweis wesentlicher Arbeitsbedingungen":"ثبت شرط‌های اصلی کار","Eine offene Vertragsangabe wird geklärt statt geraten.":"یک معلومات باز قرارداد روشن می‌شود، نه حدس زده.","Verweise auf weitere Regelwerke gehören zur Inhaltsprüfung.":"اشاره به قاعده‌نامه‌های دیگر جزو بررسی محتواست.","Brutto, Netto und Abrechnung unterscheiden":"جدا کردن ناخالص، خالص و صورت‌حساب مزد","Du unterscheidest vereinbartes Bruttoentgelt, Abzüge und tatsächlichen Auszahlungsbetrag.":"شما مزد ناخالص توافق‌شده، کسرها و مبلغ واقعی پرداخت را از هم جدا می‌کنید.","Brutto als sichere Auszahlung lesen":"ناخالص را پرداخت مطمئن خواندن","Falsch: Den monatlichen Bruttobetrag als garantierten Kontoeingang behandeln. Richtig: Abrechnung, Abzüge und weitere Positionen unterscheiden.":"اشتباه: مبلغ ناخالص ماهانه را واریز تضمین‌شده به حساب بدانید. درست: صورت‌حساب، کسرها و بخش‌های دیگر را جدا کنید.","Mit pauschalem Prozentsatz rechnen":"حساب کردن با یک درصد کلی","Falsch: Für jede Person denselben Nettobetrag aus dem Brutto ableiten. Richtig: Die individuellen Abrechnungsgrundlagen berücksichtigen.":"اشتباه: برای هر شخص همان مبلغ خالص را از ناخالص نتیجه بگیرید. درست: پایه‌های فردی صورت‌حساب را در نظر بگیرید.","Was beschreibt Brutto?":"Brutto (ناخالص) چه چیزی را توصیف می‌کند؟","Den Betrag, der nach allen Abzügen auf dem Konto eingeht.":"مبلغی که بعد از همهٔ کسرها به حساب می‌رسد.","Das Entgelt vor den entsprechenden Abzügen.":"مزد پیش از کسرهای مربوط.","Nur den Grundlohn ohne weitere Entgeltbestandteile.":"فقط مزد پایه بدون بخش‌های دیگر مزد.","Brutto ist die Ausgangsgröße vor den berücksichtigten Abzügen.":"ناخالص مقدار شروع پیش از کسرهای در نظر گرفته‌شده است.","Was hilft bei einer Abrechnungsfrage?":"در یک سوال صورت‌حساب چه چیزی کمک می‌کند؟","Nur den Kontoeingang ohne zugehörigen Abrechnungsmonat nennen.":"فقط واریز حساب را بدون ماه صورت‌حساب مربوط نام بردن.","Nur den Gesamtbetrag ohne die fragliche Position angeben.":"فقط مبلغ کل را بدون بخش مورد سوال گفتن.","Zeitraum und fragliche Position angeben.":"گفتن دوره و بخش مورد سوال.","Die konkrete Zuordnung macht die Prüfung nachvollziehbar.":"وصل کردن مشخص بررسی را قابل پیگیری می‌کند.","Warum ist eine feste Nettoquote unzuverlässig?":"چرا یک نسبت ثابت خالص قابل اعتماد نیست؟","Individuelle Grundlagen und Positionen können unterschiedlich sein.":"پایه‌ها و بخش‌های فردی ممکن است فرق داشته باشند.","Weil die Nettoquote allein von der Stellenbezeichnung abhängt.":"چون نسبت خالص فقط به عنوان کار بستگی دارد.","Weil derselbe Bruttobetrag bei allen Personen dieselbe Auszahlung ergibt.":"چون همان مبلغ ناخالص برای همه همان پرداخت را می‌دهد.","Abzüge und weitere Positionen hängen von den jeweiligen Verhältnissen ab.":"کسرها و بخش‌های دیگر به وضعیت هر شخص بستگی دارند.","Vergleiche die Abrechnung mit dem richtigen Abrechnungszeitraum und der zugrunde liegenden Vereinbarung.":"صورت‌حساب را با دورهٔ درست صورت‌حساب و توافق پایه مقایسه کنید.","Einen Betrag richtig einordnen":"درست جا دادن یک مبلغ","Kim: „Im Angebot steht ein monatliches Bruttoentgelt. Kommt derselbe Betrag auf mein Konto?“ Lohnstelle: „Nicht unbedingt. Die Abrechnung zeigt Brutto, Abzüge und Auszahlung.“ Kim: „Dann kann ich den Nettobetrag nicht ohne meine Daten berechnen?“ Lohnstelle: „Genau. Auch weitere Abrechnungspositionen müssen berücksichtigt werden.“":"کیم: «در پیشنهاد یک مزد ناخالص ماهانه نوشته شده. همان مبلغ به حسابم می‌آید؟» بخش مزد: «لزوماً نه. صورت‌حساب ناخالص، کسرها و پرداخت را نشان می‌دهد.» کیم: «پس بدون داده‌های خودم نمی‌توانم مبلغ خالص را حساب کنم؟» بخش مزد: «دقیقاً. بخش‌های دیگر صورت‌حساب هم باید در نظر گرفته شوند.»","Begriffe sauber auseinanderhalten":"جدا نگه داشتن دقیق مفهوم‌ها","Brutto bezeichnet das Entgelt vor den entsprechenden Abzügen; Netto ergibt sich nach den ausgewiesenen Abzügen. Der Auszahlungsbetrag kann durch weitere Positionen vom Netto abweichen. Deshalb ersetzt eine einfache Prozentannahme keine persönliche Abrechnung. Prüfe Zeitraum, Stundenbasis und gesonderte Zuschläge. Die vereinbarten Bestandteile sind nicht allein durch eine Kontobewegung vollständig erklärt.":"Brutto (ناخالص) مزد پیش از کسرهای مربوط است؛ Netto (خالص) بعد از کسرهای نوشته‌شده به دست می‌آید. مبلغ پرداخت ممکن است به خاطر بخش‌های دیگر با خالص فرق کند. به همین دلیل یک فرض سادهٔ درصدی جای صورت‌حساب شخصی را نمی‌گیرد. دوره، پایهٔ ساعت‌ها و اضافه‌مزدهای جداگانه را بررسی کنید. بخش‌های توافق‌شده فقط با یک حرکت حساب کامل توضیح داده نمی‌شوند.","Eine Unstimmigkeit konkret benennen":"نام بردن مشخص یک ناهماهنگی","Ein Zuschlag ist ein zusätzlicher Betrag, etwa für bestimmte Arbeitszeiten. Ein Abzug verringert den ausgewiesenen Betrag. Nenne bei einer Frage immer Monat und Position. Vergleiche einen Stundenlohn nicht direkt mit einem Monatsbetrag. Prüfe außerdem die aktuell geltenden Mindestregeln und ihre Ausnahmen. Eine feste Nettoquote gilt nicht für alle Personen.":"یک اضافه‌مزد (Zuschlag) یک مبلغ اضافی است، مثلاً برای ساعت‌های کار خاص. یک کسر مبلغ نوشته‌شده را کم می‌کند. در یک سوال همیشه ماه و بخش را نام ببرید. یک مزد ساعتی را مستقیم با یک مبلغ ماهانه مقایسه نکنید. علاوه بر آن قاعده‌های حداقل فعلی و استثناهایشان را بررسی کنید. یک نسبت ثابت خالص برای همه اعتبار ندارد.","Mit passenden Unterlagen nachfragen":"پرسیدن با اسناد مناسب","Bitte die Lohnstelle um Erklärung der konkreten Position und halte die Antwort fest. Teile nur die für die Klärung erforderlichen Daten über den vorgesehenen Weg. Bleibt ein möglicher Vergütungsanspruch offen, hole zeitnah fachkundige Hilfe; vertragliche oder tarifliche Fristen können wichtig sein. Der Vergleich in dieser Übung verwendet keine echten Steuer- oder Versicherungsdaten.":"از بخش مزد توضیح بخش مشخص را بخواهید و جواب را ثبت کنید. فقط داده‌های لازم برای روشن‌سازی را از راه پیش‌بینی‌شده بدهید. اگر یک حق احتمالی مزد باز ماند، زود کمک متخصص بگیرید؛ مهلت‌های قراردادی یا قرارداد جمعی ممکن است مهم باشند. مقایسه در این تمرین هیچ دادهٔ واقعی مالیات یا بیمه به کار نمی‌برد.","Abrechnungsbegriffe einsetzen":"گذاشتن مفهوم‌های صورت‌حساب","Setze „Brutto“ und „Abzüge“ ein.":"„Brutto“ و „Abzüge“ (کسرها) را بگذارید.","Lies die Begriffe als unterschiedliche Rechenschritte.":"مفهوم‌ها را قدم‌های مختلف حساب بخوانید.","Ein Bruttobetrag wird nicht unmittelbar mit jeder Auszahlung gleichgesetzt.":"یک مبلغ ناخالص مستقیم با هر پرداخت یکی دانسته نمی‌شود.","Entgelt vor den entsprechenden Abzügen: ___.":"Entgelt vor den entsprechenden Abzügen: ___. (مزد پیش از کسرهای مربوط: ___.)","Auf der Abrechnung ausgewiesene Minderungen: ___.":"Auf der Abrechnung ausgewiesene Minderungen: ___. (کاهش‌های نوشته‌شده در صورت‌حساب: ___.)","Positionen einordnen":"جا دادن بخش‌ها","Verbinde die Begriffe mit ihrer Funktion.":"مفهوم‌ها را به کارکردشان وصل کنید.","Eine einzelne Zahlung erklärt nicht alle Abrechnungsbestandteile.":"یک پرداخت تنها همهٔ بخش‌های صورت‌حساب را توضیح نمی‌دهد.","Die Felder betreffen Zeitraum, Berechnung und Ergebnis.":"این خانه‌ها به دوره، حساب و نتیجه مربوط‌اند.","Abrechnungsmonat":"ماه صورت‌حساب","Überstundenzuschlag":"اضافه‌مزد اضافه‌کاری","Kontoeingang":"واریز حساب","Den angebotenen Betrag verstehen":"فهمیدن مبلغ پیشنهادشده","Welche Betragsart steht im Angebot?":"در پیشنهاد کدام نوع مبلغ نوشته شده است؟","Gefragt ist die Bezeichnung des Angebots.":"نام‌گذاری پیشنهاد پرسیده شده است.","Im Angebot steht ein Bruttobetrag, keine bestätigte persönliche Nettoauszahlung.":"در پیشنهاد یک مبلغ ناخالص (Brutto) نوشته شده، نه یک پرداخت خالص شخصی تأییدشده.","Eine Abrechnungsfrage schreiben":"نوشتن یک سوال صورت‌حساب","Formuliere drei Sätze mit Monat, unklarer Position und Bitte um Erklärung, ohne einen Nettobetrag zu erfinden.":"سه جمله با ماه، بخش نامشخص و خواهش توضیح بنویسید، بدون اینکه یک مبلغ خالص بسازید.","Die Nachricht soll eine konkrete Erklärung ermöglichen.":"پیام باید یک توضیح مشخص را ممکن کند.","Der Entwurf trennt Frage, Grundlage und Auszahlung.":"این پیش‌نویس سوال، پایه و پرداخت را جدا می‌کند.","Nennst du einen eindeutigen Abrechnungsmonat?":"آیا یک ماه روشن صورت‌حساب را نام می‌برید؟","Bezeichnest du die unklare Position konkret?":"آیا بخش نامشخص را مشخص نام می‌برید؟","Bittest du um die Berechnungsgrundlage?":"آیا پایهٔ حساب را می‌خواهید؟","Vermeidest du eine erfundene Nettoquote oder Forderung?":"آیا از یک نسبت خالص یا خواستهٔ ساختگی پرهیز می‌کنید؟","Abrechnung des Arbeitsentgelts":"صورت‌حساب مزد کار","Brutto und Auszahlung sind nicht austauschbare Beträge.":"ناخالص و پرداخت مبلغ‌های قابل جابه‌جایی نیستند.","Eine Rückfrage nennt Zeitraum und konkrete Abrechnungsposition.":"یک سوال دوره و بخش مشخص صورت‌حساب را نام می‌برد.","BMAS: Mindestlohn und Vergütung":"BMAS: حداقل مزد و مزد","Arbeitszeit, Pause und Ruhezeit verstehen":"فهمیدن ساعت کار، استراحت و وقت آرامش","Du unterscheidest Arbeitsphase, Unterbrechung und Erholung zwischen Einsätzen.":"شما مرحلهٔ کار، وقفه و استراحت بین دو کار را جدا می‌کنید.","Anwesenheit immer als Arbeitszeit zählen":"حضور را همیشه ساعت کار شمردن","Falsch: Acht Stunden Anwesenheit ohne Blick auf Unterbrechungen als acht Stunden geleistete Arbeit ausweisen. Richtig: Tatsächliche Arbeit und Pausen unterscheiden.":"اشتباه: هشت ساعت حضور را بدون نگاه به وقفه‌ها هشت ساعت کار انجام‌شده نشان دهید. درست: کار واقعی و استراحت‌ها را جدا کنید.","Pause und Ruhezeit gleichsetzen":"یکی دانستن استراحت و وقت آرامش","Falsch: Die Mittagspause als gesamte Erholung zwischen zwei Einsätzen verstehen. Richtig: Ruhepause während und Ruhezeit zwischen Einsätzen getrennt prüfen.":"اشتباه: استراحت ظهر را تمام استراحت بین دو کار بفهمید. درست: استراحت در وقت کار و وقت آرامش بین کارها را جدا بررسی کنید.","Was muss bei acht Stunden Anwesenheit zusätzlich geprüft werden?":"در هشت ساعت حضور چه چیزی را باید اضافه بررسی کرد؟","Nur die laut Dienstplan vorgesehene Gesamtanwesenheit.":"فقط حضور کلی پیش‌بینی‌شده در برنامهٔ کار.","Nur die vereinbarte Wochenstundenzahl ohne Tagesablauf.":"فقط تعداد توافق‌شدهٔ ساعت‌های هفته بدون روند روز.","Die tatsächlichen Arbeits- und Pausenzeiten.":"ساعت‌های واقعی کار و استراحت.","Anwesenheit allein sagt nicht, welche Unterbrechungen enthalten sind.":"حضور به تنهایی نمی‌گوید کدام وقفه‌ها در آن هستند.","Was bezeichnet die Ruhezeit im Beispiel?":"در مثال Ruhezeit (وقت آرامش) چه چیزی را نام می‌برد؟","Die Erholung zwischen den Einsätzen.":"استراحت بین کارها.","Die Mittagspause innerhalb derselben Schicht.":"استراحت ظهر در همان نوبت.","Die Fahrtzeit vom Betrieb nach Hause.":"وقت رفتن از شرکت به خانه.","Die Ruhezeit betrifft den Abstand zwischen Einsätzen, nicht die Mittagspause.":"وقت آرامش به فاصلهٔ بین کارها مربوط است، نه به استراحت ظهر.","Welche Erfassung ist sachlich korrekt?":"کدام ثبت از نظر محتوا درست است؟","Die geplanten Zeiten auch dann, wenn tatsächlich anders gearbeitet wurde.":"وقت‌های برنامه‌ریزی‌شده حتی اگر در واقع جور دیگری کار شده باشد.","Der tatsächliche Beginn, das Ende und echte Unterbrechungen.":"شروع واقعی، پایان و وقفه‌های واقعی.","Eine eingetragene Pause, während der weitergearbeitet wurde.":"یک استراحت ثبت‌شده که در آن کار ادامه داشت.","Der Nachweis soll tatsächliche Zeiten statt bloßer Planung abbilden.":"ثبت باید وقت‌های واقعی را نشان دهد، نه فقط برنامه را.","Notiere Beginn, Ende und tatsächliche Unterbrechungen getrennt, statt Anwesenheit automatisch als Arbeitszeit zu behandeln.":"شروع، پایان و وقفه‌های واقعی را جدا یادداشت کنید، به جای اینکه حضور را خودکار ساعت کار حساب کنید.","Einen Zeitplan prüfen":"بررسی یک برنامهٔ وقت","Mert: „Ich bin von acht bis sechzehn Uhr im Betrieb. Das sind acht Stunden Arbeit?“ Kollegin: „Nicht automatisch. Wir müssen die tatsächliche Pause getrennt betrachten.“ Mert: „Und die Ruhezeit?“ Kollegin: „Das ist die Zeit zwischen den Einsätzen, nicht dieselbe Unterbrechung wie die Mittagspause.“":"مرت: «من از هشت تا شانزده در شرکت هستم. این هشت ساعت کار است؟» همکارش: «خودکار نه. باید استراحت واقعی را جدا ببینیم.» مرت: «و وقت آرامش؟» همکارش: «این وقت بین کارهاست، نه همان وقفهٔ استراحت ظهر.»","Drei Zeitbegriffe auseinanderhalten":"جدا نگه داشتن سه مفهوم وقت","Arbeitszeit ist die Zeit, in der du arbeitest. Eine Ruhepause unterbricht den Einsatz. Die Ruhezeit liegt zwischen zwei Einsätzen. § 3 ArbZG sieht grundsätzlich acht werktägliche Stunden vor. Bis zu zehn sind nur mit dem gesetzlich nötigen Ausgleich erlaubt. Sonderregeln können gelten. Ein Vertrag darf deshalb nicht jede beliebige Arbeitsdauer erlauben.":"Arbeitszeit (ساعت کار) وقتی است که کار می‌کنید. یک Ruhepause (استراحت) کار را قطع می‌کند. Ruhezeit (وقت آرامش) بین دو کار است. § 3 ArbZG اصولاً هشت ساعت در روز کاری را پیش‌بینی می‌کند. تا ده ساعت فقط با جبران قانونی لازم مجاز است. قاعده‌های خاص ممکن است اعتبار داشته باشند. به همین دلیل یک قرارداد نمی‌تواند هر مدت دلخواه کار را اجازه دهد.","Den tatsächlichen Ablauf erfassen":"ثبت روند واقعی","Erfasse, wann du wirklich beginnst und aufhörst. Notiere auch echte Pausen nach dem vorgesehenen Verfahren. Eine Pause im Dienstplan ist nicht unbedingt eine genommene Pause. Hast du weitergearbeitet, muss die Aufzeichnung den tatsächlichen Ablauf zeigen. Frage bei unklaren Eingaben nach, statt Zeiten passend zu machen.":"ثبت کنید که واقعاً چه وقت شروع می‌کنید و تمام می‌کنید. استراحت‌های واقعی را هم با روش پیش‌بینی‌شده یادداشت کنید. یک استراحت در برنامهٔ کار لزوماً استراحت گرفته‌شده نیست. اگر کار را ادامه داده‌اید، ثبت باید روند واقعی را نشان دهد. در نوشته‌های نامشخص بپرسید، به جای اینکه وقت‌ها را جور کنید.","Unklarheiten mit dem Plan abgleichen":"مقایسهٔ نامشخصی‌ها با برنامه","Frage, wie Pausen, Bereitschaft oder zusätzliche Arbeit im konkreten System erfasst werden. Eine freiwillige Schätzung ersetzt keinen korrekten Nachweis. Bei Zweifeln an der Einhaltung der Regeln wende dich an die zuständige Stelle im Betrieb oder fachkundige Beratung. Die beispielhaften Uhrzeiten hier sind kein rechtlicher Freigabeplan für einen konkreten Einsatz.":"بپرسید که استراحت‌ها، آماده‌باش یا کار اضافی در سیستم مشخص چطور ثبت می‌شوند. یک تخمین داوطلبانه جای یک ثبت درست را نمی‌گیرد. اگر دربارهٔ رعایت قاعده‌ها شک دارید، به بخش مسئول در شرکت یا یک مشورهٔ متخصص مراجعه کنید. ساعت‌های نمونه در اینجا برنامهٔ اجازهٔ حقوقی برای یک کار مشخص نیستند.","Zeitbegriffe ergänzen":"کامل کردن مفهوم‌های وقت","Setze „Ruhepause“ und „Ruhezeit“ ein.":"„Ruhepause“ (استراحت) و „Ruhezeit“ (وقت آرامش) را بگذارید.","Ordne nach dem Zeitpunkt der Erholung.":"بر اساس وقت استراحت وصل کنید.","Die Begriffe dürfen bei der Prüfung nicht verwechselt werden.":"این مفهوم‌ها در بررسی نباید با هم اشتباه شوند.","Unterbrechung während des Einsatzes: ___.":"Unterbrechung während des Einsatzes: ___. (وقفه در وقت کار: ___.)","Erholung zwischen den Einsätzen: ___.":"Erholung zwischen den Einsätzen: ___. (استراحت بین کارها: ___.)","Zeitangaben zuordnen":"وصل کردن معلومات وقت","Verbinde Angabe und Funktion.":"معلومات و کارکرد را وصل کنید.","Der Ablauf muss vollständig statt nur mit einem Gesamtwert beschrieben werden.":"روند باید کامل توصیف شود، نه فقط با یک عدد کلی.","Einzelangaben ermöglichen die Prüfung des Zeitnachweises.":"معلومات جداگانه بررسی ثبت وقت را ممکن می‌کنند.","8 Uhr starten":"ساعت 8 شروع","16 Uhr aufhören":"ساعت 16 پایان","tatsächlich nicht arbeiten":"واقعاً کار نکردن","Den Anwesenheitsbeginn hören":"شنیدن شروع حضور","Um wie viel Uhr beginnt Merts Anwesenheit? Schreibe eine Ziffer.":"حضور مرت چه ساعتی شروع می‌شود؟ یک رقم بنویسید.","Gefragt ist der Beginn, nicht eine berechnete Arbeitsdauer.":"شروع پرسیده شده، نه یک مدت کار حساب‌شده.","Mert nennt 8 Uhr als Beginn.":"مرت ساعت 8 را شروع نام می‌برد.","Eine Zeitklärungsfrage formulieren":"نوشتن یک سوال روشن‌سازی وقت","Schreibe drei Sätze zur Anwesenheit 8–16 Uhr und bitte um Klärung der Pausenerfassung.":"سه جمله دربارهٔ حضور ساعت 8 تا 16 بنویسید و روشن‌سازی ثبت استراحت را بخواهید.","Frage nach dem konkreten Ablauf statt eine pauschale Stundenzahl zu behaupten.":"دربارهٔ روند مشخص بپرسید، به جای اینکه یک تعداد کلی ساعت را ادعا کنید.","Die Nachricht ermöglicht eine richtige und vollständige Aufzeichnung.":"این پیام یک ثبت درست و کامل را ممکن می‌کند.","Unterscheidest du Anwesenheit und geleistete Arbeitszeit?":"آیا حضور و ساعت کار انجام‌شده را جدا می‌کنید؟","Nennst du die tatsächliche Pause als eigenen Prüfpunkt?":"آیا استراحت واقعی را یک نکتهٔ جداگانهٔ بررسی نام می‌برید؟","Fragst du nach dem vorgesehenen Erfassungsweg?":"آیا دربارهٔ راه پیش‌بینی‌شدهٔ ثبت می‌پرسید؟","Vermeidest du einen ungeprüften rechtlichen Einsatzplan?":"آیا از یک برنامهٔ کار حقوقی بررسی‌نشده پرهیز می‌کنید؟","Stand: November 2026. Allgemeine Information, keine Rechtsberatung. Prüfe aktuelle Regeln bei bmas.de.":"وضعیت: نوامبر 2026. معلومات عمومی، نه مشورهٔ حقوقی. قاعده‌های فعلی را در bmas.de بررسی کنید.","BMAS: Arbeitszeitregeln":"BMAS: قاعده‌های ساعت کار","Zeitnachweise sollen den tatsächlichen Ablauf wiedergeben.":"ثبت‌های وقت باید روند واقعی را نشان دهند.","Eine Verlängerung der Arbeitszeit braucht die passenden gesetzlichen Voraussetzungen.":"زیاد کردن ساعت کار شرط‌های قانونی مناسب لازم دارد.","Arbeitszeitgesetz":"قانون ساعت کار (Arbeitszeitgesetz)","Gesetzliche Ruhepausen":"استراحت‌های قانونی","Gesetzliche Ruhezeit":"وقت آرامش قانونی","Urlaub beantragen und den Status klären":"درخواست رخصتی و روشن کردن وضعیت آن","Du unterscheidest Urlaubswunsch, Antrag und gewährten Zeitraum.":"شما خواستهٔ رخصتی، درخواست و دورهٔ تأییدشده را جدا می‌کنید.","Antrag mit Genehmigung gleichsetzen":"درخواست را تأیید دانستن","Falsch: „Ich habe beantragt, also ist der Urlaub bestätigt.“ Richtig: Den tatsächlichen Gewährungsstatus und offene Rückfragen klären.":"اشتباه: «درخواست داده‌ام، پس رخصتی تأیید شده است.» درست: وضعیت واقعی تأیید و سوال‌های باز را روشن کنید.","Urlaubstage ohne Arbeitsmodell übertragen":"انتقال روزهای رخصتی بدون مدل کار","Falsch: Jede Zahl unverändert auf jede Wochenverteilung anwenden. Richtig: Anspruch und regelmäßige Arbeitstage passend prüfen.":"اشتباه: هر عدد را بدون تغییر بر هر تقسیم هفته به کار ببرید. درست: حق و روزهای منظم کار را مناسب بررسی کنید.","Welchen Status hat Rosas Urlaub?":"رخصتی روزا کدام وضعیت را دارد؟","Bereits gewährter Zeitraum ohne weitere Rückfrage.":"دورهٔ از قبل تأییدشده بدون سوال دیگر.","Noch offen mit Rückfrage zur Vertretung.":"هنوز باز با یک سوال دربارهٔ جانشین.","Abgelehnter Antrag trotz noch offener Rückmeldung.":"درخواست ردشده با وجود جواب هنوز باز.","Rosa hat beantragt, aber noch keine Genehmigung erhalten.":"روزا درخواست داده، اما هنوز تأیید نگرفته است.","Den gewünschten Zeitraum ohne Rückmeldung als genehmigt eintragen.":"دورهٔ دلخواه را بدون جواب تأییدشده نوشتن.","Die offene Anfrage als automatische Ablehnung behandeln.":"درخواست باز را رد خودکار حساب کردن.","Die Vertretungsfrage und Rückmeldung klären.":"سوال جانشین و جواب را روشن کردن.","Die offene Bedingung wird mit dem Betrieb besprochen statt selbst als erledigt behandelt.":"شرط باز با شرکت صحبت می‌شود، نه اینکه خودتان آن را انجام‌شده حساب کنید.","Was ist beim Vergleich von Urlaubstagen wichtig?":"در مقایسهٔ روزهای رخصتی چه چیزی مهم است؟","Die Verteilung der regelmäßigen Arbeitstage.":"تقسیم روزهای منظم کار.","Nur die Zahl aus dem Vertrag einer anderen Wochenverteilung.":"فقط عدد قرارداد یک تقسیم هفتهٔ دیگر.","Nur die Länge des gewünschten Zeitraums ohne Anspruchsprüfung.":"فقط طول دورهٔ دلخواه بدون بررسی حق.","Die Zahl der Arbeitstage beeinflusst die sachgerechte Einordnung eines Urlaubsanspruchs.":"تعداد روزهای کار بر جا دادن درست یک حق رخصتی اثر دارد.","Dokumentiere nach dem Antrag die tatsächliche Rückmeldung, bevor du den Zeitraum als bestätigt behandelst.":"بعد از درخواست جواب واقعی را ثبت کنید، پیش از اینکه دوره را تأییدشده حساب کنید.","Eine noch offene Anfrage besprechen":"صحبت دربارهٔ یک درخواست هنوز باز","Rosa: „Ich habe Urlaub für die zweite Juliwoche beantragt.“ Kollege: „Ist er schon genehmigt?“ Rosa: „Noch nicht, es gibt eine Rückfrage zur Vertretung.“ Kollege: „Dann ist der Antrag noch offen.“ Rosa: „Ich kläre die Vertretung und bitte um eine eindeutige Rückmeldung.“":"روزا: «برای هفتهٔ دوم جولای درخواست رخصتی داده‌ام.» همکارش: «تأیید شده؟» روزا: «هنوز نه، یک سوال دربارهٔ جانشین هست.» همکارش: «پس درخواست هنوز باز است.» روزا: «جانشین را روشن می‌کنم و یک جواب روشن می‌خواهم.»","Wunsch und Gewährung auseinanderhalten":"جدا نگه داشتن خواسته و تأیید","§ 7 BUrlG regelt, wann du Urlaub nimmst. Der Arbeitgeber muss deine Wünsche berücksichtigen. Dringende betriebliche Gründe oder vorrangige Urlaubswünsche anderer können entgegenstehen. Ein Antrag ist noch keine Bestätigung. Kläre den Antragsweg und warte auf eine eindeutige Rückmeldung. Nimm einen ungeklärten Urlaub nicht einfach selbst.":"§ 7 BUrlG تنظیم می‌کند که چه وقت رخصتی می‌گیرید. کارفرما باید خواسته‌های شما را در نظر بگیرد. دلیل‌های فوری شرکت یا خواسته‌های رخصتی مقدم دیگران ممکن است مانع شوند. یک درخواست هنوز تأیید نیست. راه درخواست را روشن کنید و منتظر یک جواب روشن بمانید. یک رخصتی روشن‌نشده را همین طوری خودتان نگیرید.","Urlaubsangaben nachvollziehbar lesen":"خواندن قابل پیگیری معلومات رخصتی","Prüfe, an welchen Tagen du normalerweise arbeitest. Davon hängt ab, wie Urlaubstage auf deinen Arbeitsplan umgerechnet werden. Übernimm nicht einfach die Zahl aus einem anderen Arbeitsmodell. Stelle den Antrag über den vorgesehenen Weg. Bewahre die Rückmeldung auf. Erst daraus erkennst du, welcher Zeitraum gewährt ist.":"بررسی کنید که معمولاً در کدام روزها کار می‌کنید. به این بستگی دارد که روزهای رخصتی چطور بر برنامهٔ کار شما حساب شوند. عدد یک مدل کار دیگر را همین طوری نگیرید. درخواست را از راه پیش‌بینی‌شده بدهید. جواب را نگه دارید. فقط از آن می‌فهمید کدام دوره تأیید شده است.","Bei Problemen zeitnah klären":"روشن کردن زود در مشکلات","Notiere den angefragten Zeitraum und die konkrete offene Frage. Bitte um Erklärung, wenn eine Rückmeldung unklar ist. Ob Urlaub ins nächste Jahr übertragen wird oder verfällt, hängt von weiteren Regeln und Voraussetzungen ab. Lass deinen Fall prüfen. Bei Streit helfen die zuständigen betrieblichen Stellen oder eine rechtliche Beratung.":"دورهٔ خواسته‌شده و سوال باز مشخص را یادداشت کنید. اگر یک جواب نامشخص است، توضیح بخواهید. اینکه رخصتی به سال بعد منتقل می‌شود یا از بین می‌رود، به قاعده‌ها و شرط‌های دیگر بستگی دارد. بگذارید مورد شما بررسی شود. در اختلاف، بخش‌های مسئول شرکت یا یک مشورهٔ حقوقی کمک می‌کنند.","Den Status ergänzen":"کامل کردن وضعیت","Setze „beantragt“ und „offen“ ein.":"„beantragt“ (درخواست‌شده) و „offen“ (باز) را بگذارید.","Unterscheide eigene Handlung und Entscheidung.":"کار خودتان و تصمیم را جدا کنید.","Ein gestellter Antrag ist noch kein bestätigter Zeitraum.":"یک درخواست داده‌شده هنوز دورهٔ تأییدشده نیست.","Rosa hat den Urlaub ___.":"Rosa hat den Urlaub ___. (روزا رخصتی را ___.)","Ohne klare Rückmeldung bleibt der Antrag ___.":"Ohne klare Rückmeldung bleibt der Antrag ___. (بدون جواب روشن درخواست ___ می‌ماند.)","Urlaubsschritte zuordnen":"وصل کردن قدم‌های رخصتی","Ordne die Angaben zu.":"معلومات را وصل کنید.","Der Stand muss für die weitere Planung sichtbar bleiben.":"وضعیت باید برای برنامه‌ریزی بعدی قابل دید بماند.","Die Zuordnung verhindert eine voreilige Bestätigung.":"این وصل کردن از یک تأیید عجولانه جلوگیری می‌کند.","zweite Juliwoche":"هفتهٔ دوم جولای","Vertretung unklar":"جانشین نامشخص","eindeutige Rückmeldung":"جواب روشن","Die offene Frage hören":"شنیدن سوال باز","Welcher Punkt muss noch geklärt werden?":"کدام نکته هنوز باید روشن شود؟","Gesucht ist der konkrete offene Punkt.":"نکتهٔ باز مشخص پرسیده شده است.","Die Rückfrage betrifft die Vertretung.":"سوال به جانشین (Vertretung) مربوط است.","Eine Rückfrage zum Urlaub schreiben":"نوشتن یک سوال دربارهٔ رخصتی","Schreibe drei Sätze zu Antrag, offener Vertretungsfrage und Bitte um Rückmeldung.":"سه جمله دربارهٔ درخواست، سوال باز جانشین و خواهش جواب بنویسید.","Dokumentiere den Stand, bevor du ihn in deinem Kalender als bestätigt markierst.":"وضعیت را ثبت کنید، پیش از اینکه آن را در تقویم خود تأییدشده علامت بزنید.","Die Anfrage bleibt bei den offenen Punkten des Beispiels.":"این درخواست به نکته‌های باز مثال بسنده می‌کند.","Ist der gewünschte Zeitraum genannt?":"آیا دورهٔ دلخواه نام برده شده است؟","Bleibt der Antrag als unbestätigt erkennbar?":"آیا درخواست تأییدنشده شناخته می‌ماند؟","Beziehst du dich auf die Vertretungsfrage?":"آیا به سوال جانشین اشاره می‌کنید؟","Bittest du um eine eindeutige Entscheidung statt sie vorauszusetzen?":"آیا یک تصمیم روشن می‌خواهید، به جای اینکه آن را فرض کنید؟","Zeitpunkt und Übertragung des Urlaubs":"وقت و انتقال رخصتی","Ein Urlaubsantrag ist vom gewährten Zeitraum zu unterscheiden.":"یک درخواست رخصتی از دورهٔ تأییدشده جداست.","Eine unklare Rückmeldung wird vor der weiteren Planung präzisiert.":"یک جواب نامشخص پیش از برنامه‌ریزی بعدی دقیق می‌شود.","Urlaubsgewährung":"تأیید رخصتی","Arbeitsunfähigkeit richtig melden":"گزارش درست ناتوانی کار","Arbeitsunfähigkeit heißt hier: Wegen Krankheit kannst du deine Arbeit nicht ausführen. Du lernst, was du melden und ärztlich klären musst.":"ناتوانی کار (Arbeitsunfähigkeit) اینجا یعنی: به خاطر بیماری نمی‌توانید کار خود را انجام دهید. یاد می‌گیرید چه چیزی را باید گزارش دهید و نزد داکتر روشن کنید.","Elektronischen Nachweis als eigene Meldung ansehen":"ثبت الکترونیکی را گزارش خودتان دانستن","Falsch: Wegen elektronischer Datenübermittlung gar nicht beim Arbeitgeber melden. Richtig: Die eigene Mitteilung unverzüglich über den vorgesehenen Weg vornehmen.":"اشتباه: به خاطر فرستادن الکترونیکی داده‌ها اصلاً به کارفرما خبر ندهید. درست: گزارش خودتان را بی‌درنگ از راه پیش‌بینی‌شده بدهید.","Eine sichere Dauer erfinden":"ساختن یک مدت مطمئن","Falsch: Ohne Grundlage eine feste Rückkehr garantieren. Richtig: Voraussichtliche Dauer mitteilen und Änderungen nachmelden.":"اشتباه: بدون پایه یک بازگشت قطعی را تضمین کنید. درست: مدت احتمالی را بگویید و تغییرها را بعداً گزارش دهید.","Was bleibt trotz elektronischem Ablauf nötig?":"با وجود روند الکترونیکی چه چیزی لازم می‌ماند؟","Nur das Abwarten des elektronischen Abrufs ohne eigene Nachricht.":"فقط منتظر دریافت الکترونیکی ماندن بدون پیام خودتان.","Nur die spätere Rückkehrmeldung nach Ende der Erkrankung.":"فقط گزارش بازگشت بعد از پایان بیماری.","Die unverzügliche eigene Mitteilung.":"گزارش بی‌درنگ خودتان.","Die Anzeige der Arbeitsunfähigkeit ist von der elektronischen Abwicklung zu unterscheiden.":"اعلام ناتوانی کار از روند الکترونیکی جداست.","Welche Dauer wird mitgeteilt?":"کدام مدت گفته می‌شود؟","Die voraussichtliche Dauer nach dem bekannten Stand.":"مدت احتمالی بر اساس وضعیت دانسته‌شده.","Eine feste Rückkehr, obwohl sie noch nicht eingeschätzt werden kann.":"یک بازگشت قطعی، با اینکه هنوز نمی‌توان آن را برآورد کرد.","Nur den Zeitpunkt des Arzttermins statt der erwarteten Dauer.":"فقط وقت ملاقات داکتر به جای مدت مورد انتظار.","Die Mitteilung folgt dem tatsächlich bekannten voraussichtlichen Zeitraum.":"گزارش از دورهٔ احتمالی واقعاً دانسته‌شده پیروی می‌کند.","Warum ist „immer erst nach drei Tagen“ unzureichend?":"چرا «همیشه فقط بعد از سه روز» کافی نیست؟","Weil die eigene Meldung bis zur ersten Abrechnung warten kann.":"چون گزارش خودتان می‌تواند تا اولین صورت‌حساب صبر کند.","Weil frühere Feststellung und besondere Abläufe relevant sein können.":"چون تأیید زودتر و روندهای خاص ممکن است مهم باشند.","Weil die elektronische Übermittlung die ärztliche Feststellung ersetzt.":"چون فرستادن الکترونیکی جای تأیید داکتر را می‌گیرد.","Das Gesetz sieht differenzierte Feststellungs- und Nachweisregeln vor.":"قانون قاعده‌های سنجیدهٔ تأیید و ثبت را پیش‌بینی می‌کند.","Kläre vorab den betrieblichen Meldeweg und behalte Mitteilung und Nachweis als zwei eigene Aufgaben im Blick.":"از قبل راه گزارش شرکت را روشن کنید و گزارش و ثبت را دو کار جداگانه در نظر داشته باشید.","Eine Arbeitsunfähigkeit mitteilen":"گزارش یک ناتوانی کار","Mira: „Ich bin heute arbeitsunfähig und informiere sofort die zuständige Stelle. Die voraussichtliche Dauer kläre ich ärztlich und teile sie mit, sobald sie feststeht.“ Freundin: „Übernimmt das nicht alles die elektronische Bescheinigung?“ Mira: „Die eigene Meldung entfällt dadurch nicht. Den konkreten Nachweisablauf muss ich zusätzlich beachten.“":"میرا: «امروز ناتوان از کار هستم و فوراً به بخش مسئول خبر می‌دهم. مدت احتمالی را نزد داکتر روشن می‌کنم و همین که معلوم شد، اطلاع می‌دهم.» دوستش: «آیا تصدیق الکترونیکی همهٔ این‌ها را انجام نمی‌دهد؟» میرا: «گزارش خودم با این از بین نمی‌رود. روند مشخص ثبت را هم باید جداگانه رعایت کنم.»","Mitteilung und Nachweis unterscheiden":"جدا کردن گزارش و ثبت","§ 5 EntgFG verlangt, dass du Arbeitsunfähigkeit und voraussichtliche Dauer unverzüglich meldest. Das heißt: ohne schuldhaftes Warten. Dazu kommen ärztliche Feststellung und Nachweis. Für viele gesetzlich Versicherte gilt ein elektronischer Ablauf. Das gilt nicht in jedem Fall. Der Arbeitgeber kann die ärztliche Feststellung früher verlangen. Warte deshalb nicht pauschal drei Tage.":"§ 5 EntgFG می‌خواهد که ناتوانی کار و مدت احتمالی را بی‌درنگ گزارش دهید. یعنی: بدون انتظار مقصرانه. علاوه بر آن تأیید داکتر و ثبت لازم است. برای بسیاری از بیمه‌شدگان قانونی یک روند الکترونیکی اعتبار دارد. این در هر مورد صادق نیست. کارفرما می‌تواند تأیید داکتر را زودتر بخواهد. پس کلی سه روز صبر نکنید.","Klar und ohne unnötige Details melden":"گزارش روشن و بدون جزئیات غیرلازم","Melde, dass du nicht arbeiten kannst und wie lange das voraussichtlich dauert. Ist die Dauer noch unklar, sage das offen. Erfinde keine feste Rückkehr. Dauert die Arbeitsunfähigkeit länger, informiere den Betrieb erneut. Kläre auch, ob eine weitere ärztliche Feststellung nötig ist. Nutze dafür den vereinbarten Meldeweg.":"گزارش دهید که نمی‌توانید کار کنید و احتمالاً چقدر طول می‌کشد. اگر مدت هنوز نامشخص است، آشکارا بگویید. هیچ بازگشت قطعی نسازید. اگر ناتوانی کار بیشتر طول کشید، دوباره به شرکت خبر دهید. همچنین روشن کنید که آیا یک تأیید دیگر داکتر لازم است. برای آن راه گزارش توافق‌شده را به کار ببرید.","Den konkreten Ablauf absichern":"محکم کردن روند مشخص","Kläre, wen du im Betrieb erreichst und wie du dich meldest. Elektronische Daten ersetzen deine eigene Meldung nicht. Frage bei besonderen Fällen nach dem passenden Ablauf, etwa bei einer Erkrankung im Ausland. Musst du länger fehlen, aktualisiere deine Angaben. In dieser Übung schreibst du eine Meldung ohne Diagnose oder echte Gesundheitsdokumente.":"روشن کنید در شرکت به چه کسی دسترسی دارید و چطور گزارش می‌دهید. داده‌های الکترونیکی جای گزارش خودتان را نمی‌گیرند. در موردهای خاص، مثلاً بیماری در خارج، دربارهٔ روند مناسب بپرسید. اگر باید بیشتر غیرحاضر باشید، معلومات خود را تازه کنید. در این تمرین یک گزارش بدون تشخیص بیماری یا اسناد واقعی صحی می‌نویسید.","Die Meldung ergänzen":"کامل کردن گزارش","Setze „arbeitsunfähig“ und „Dauer“ ein.":"„arbeitsunfähig“ (ناتوان از کار) و „Dauer“ (مدت) را بگذارید.","Die Meldung betrifft Arbeitsfähigkeit und erwarteten Zeitraum.":"گزارش به توانایی کار و دورهٔ مورد انتظار مربوط است.","Diese Informationen sind von einer ausführlichen Diagnose zu unterscheiden.":"این معلومات از یک تشخیص مفصل بیماری جداست.","Mira teilt mit, dass sie ___ ist.":"Mira teilt mit, dass sie ___ ist. (میرا اطلاع می‌دهد که ___ است.)","Sie nennt die voraussichtliche ___.":"Sie nennt die voraussichtliche ___. (او ___ احتمالی را نام می‌برد.)","Aufgaben trennen":"جدا کردن کارها","Ordne die Handlung zu.":"کار را وصل کنید.","Die Aufgaben können zeitlich zusammenhängen, bleiben aber verschieden.":"این کارها ممکن است از نظر وقت به هم مربوط باشند، اما جدا می‌مانند.","Ein Schritt ersetzt nicht automatisch die anderen.":"یک قدم خودکار جای قدم‌های دیگر را نمی‌گیرد.","Arbeitgeber informieren":"خبر دادن به کارفرما","Arbeitsunfähigkeit ärztlich klären":"روشن کردن ناتوانی کار نزد داکتر","Verlängerung bekanntgeben":"اعلام تمدید","Den eigenen Schritt hören":"شنیدن قدم خودتان","Wen informiert Mira über ihre Arbeitsunfähigkeit?":"میرا به چه کسی دربارهٔ ناتوانی کار خود خبر می‌دهد؟","Gesucht ist der Empfänger der eigenen Mitteilung.":"گیرندهٔ گزارش خودتان پرسیده شده است.","Mira meldet die Arbeitsunfähigkeit beim Arbeitgeber.":"میرا ناتوانی کار را به کارفرما (Arbeitgeber) گزارش می‌دهد.","Eine knappe Mitteilung formulieren":"نوشتن یک گزارش کوتاه","Schreibe drei Sätze: heute arbeitsunfähig, Dauer noch ärztlich zu klären, weitere Information folgt.":"سه جمله بنویسید: امروز ناتوان از کار، مدت هنوز باید نزد داکتر روشن شود، معلومات بیشتر می‌آید.","Schreibe nur den tatsächlich bekannten Stand.":"فقط وضعیت واقعاً دانسته‌شده را بنویسید.","Das Muster meldet frühzeitig und ergänzt keine ungeklärte Dauer.":"این نمونه زود گزارش می‌دهد و هیچ مدت روشن‌نشده‌ای اضافه نمی‌کند.","Meldest du die Arbeitsunfähigkeit eindeutig?":"آیا ناتوانی کار را روشن گزارش می‌دهید؟","Bleibt die noch unbekannte Dauer als offen bezeichnet?":"آیا مدت هنوز نامعلوم باز نامیده می‌ماند؟","Sagst du eine Aktualisierung nach Klärung zu?":"آیا وعدهٔ تازه کردن بعد از روشن‌سازی می‌دهید؟","Vermeidest du eine erfundene ärztliche Bestätigung oder Diagnose?":"آیا از یک تأیید ساختگی داکتر یا تشخیص پرهیز می‌کنید؟","Arbeitsunfähigkeit melden und nachweisen":"گزارش و ثبت ناتوانی کار","Die eigene Mitteilung entfällt durch den elektronischen Ablauf nicht.":"گزارش خودتان با روند الکترونیکی از بین نمی‌رود.","Ärztliche Feststellung und Meldeweg werden im konkreten Fall geprüft.":"تأیید داکتر و راه گزارش در مورد مشخص بررسی می‌شوند.","Anzeige und Nachweis der Arbeitsunfähigkeit":"اعلام و ثبت ناتوانی کار","Probezeit und Befristung getrennt lesen":"خواندن جداگانهٔ دورهٔ آزمایشی و قرارداد مدت‌دار","Die Befristung begrenzt die Vertragsdauer. Die Probezeit ist die vereinbarte erste Zeit, in der Betrieb und Beschäftigte die Zusammenarbeit erproben.":"Befristung (مدت‌دار بودن) مدت قرارداد را محدود می‌کند. Probezeit (دورهٔ آزمایشی) وقت اول توافق‌شده است که شرکت و کارمند همکاری را آزمایش می‌کنند.","Probezeit als Vertragsende lesen":"دورهٔ آزمایشی را پایان قرارداد خواندن","Falsch: „Nach der Probezeit endet jeder Vertrag automatisch.“ Richtig: Probezeit und vereinbartes Ende der Befristung getrennt lesen.":"اشتباه: «بعد از دورهٔ آزمایشی هر قرارداد خودکار تمام می‌شود.» درست: دورهٔ آزمایشی و پایان توافق‌شدهٔ قرارداد مدت‌دار را جدا بخوانید.","Möglichkeit als Verlängerungszusage verstehen":"امکان را وعدهٔ تمدید فهمیدن","Falsch: „Vielleicht länger“ als bereits vereinbarte Verlängerung notieren. Richtig: Die Verlängerung ausdrücklich klären.":"اشتباه: «شاید طولانی‌تر» را تمدید از قبل توافق‌شده یادداشت کنید. درست: تمدید را صریحاً روشن کنید.","Welche Angabe betrifft das vereinbarte Ende?":"کدام معلومات به پایان توافق‌شده مربوط است؟","Die Befristung.":"مدت‌دار بودن (Befristung).","Die anfängliche Probephase unabhängig vom Enddatum.":"مرحلهٔ آزمایشی اول بدون ربط با تاریخ پایان.","Nur die erste im Vertrag erwähnte Kündigungsfrist.":"فقط اولین مهلت فسخ که در قرارداد آمده.","Die Befristung beschreibt die zeitliche Begrenzung, nicht bloß die anfängliche Erprobung.":"مدت‌دار بودن محدودیت زمانی را توصیف می‌کند، نه فقط آزمایش اول را.","Was bedeutet „vielleicht länger“?":"«شاید طولانی‌تر» یعنی چه؟","Eine bereits abgeschlossene Verlängerungsvereinbarung.":"یک توافق تمدید از قبل بسته‌شده.","Eine bestätigte Änderung des bisher genannten Enddatums.":"یک تغییر تأییدشدهٔ تاریخ پایان تا حالا.","Eine Möglichkeit ohne bereits bestätigte Verlängerung.":"یک امکان بدون تمدید از قبل تأییدشده.","Eine unbestimmte Aussicht ersetzt keine geklärte Vereinbarung.":"یک چشم‌انداز نامعین جای یک توافق روشن‌شده را نمی‌گیرد.","Was ist bei einer persönlichen Kündigungsfrage nötig?":"در یک سوال شخصی فسخ چه چیزی لازم است؟","Nur die Dauer der Probezeit ohne weitere Klauseln lesen.":"فقط مدت دورهٔ آزمایشی را بدون بندهای دیگر خواندن.","Die konkreten Regeln und Unterlagen prüfen lassen.":"گذاشتن اینکه قاعده‌ها و اسناد مشخص بررسی شوند.","Die Frist aus einem fremden Mustervertrag unverändert übernehmen.":"مهلت را از یک قرارداد نمونهٔ دیگر بدون تغییر گرفتن.","Vertrag, Gesetz und mögliche weitere Regelungen können zusammenwirken.":"قرارداد، قانون و قاعده‌های دیگر احتمالی ممکن است با هم اثر کنند.","Markiere in einem fiktiven Vertrag Probezeit und Enddatum in zwei verschiedenen Farben.":"در یک قرارداد ساختگی دورهٔ آزمایشی و تاریخ پایان را با دو رنگ مختلف علامت بزنید.","Zwei Zeitangaben unterscheiden":"جدا کردن دو معلومات وقت","Firas: „Mein Vertrag nennt ein Enddatum und eine Probezeit am Anfang.“ Beraterin: „Das sind verschiedene Angaben. Die Befristung betrifft die Dauer. Die Probezeit dient dazu, die Zusammenarbeit zu erproben.“ Firas: „Dann endet der Vertrag nicht automatisch am Ende der Probezeit?“ Beraterin: „Genau. Prüfen Sie beide Angaben getrennt.“":"فراس: «قرارداد من یک تاریخ پایان و یک دورهٔ آزمایشی در آغاز را نام می‌برد.» مشاور: «این‌ها معلومات مختلف‌اند. مدت‌دار بودن به مدت مربوط است. دورهٔ آزمایشی برای آزمایش همکاری است.» فراس: «پس قرارداد خودکار در پایان دورهٔ آزمایشی تمام نمی‌شود؟» مشاور: «دقیقاً. هر دو معلومات را جدا بررسی کنید.»","Ein festes Enddatum erkennen":"شناختن یک تاریخ پایان ثابت","Steht ein wirksam vereinbartes Enddatum fest, endet ein kalendermäßig befristeter Vertrag grundsätzlich mit diesem Datum. § 15 TzBfG enthält weitere Regeln. Bei einer Zweckbefristung ist statt eines Datums ein bestimmter Zweck vereinbart. Auch für eine ordentliche Kündigung gelten besondere Voraussetzungen. Lass bei Zweifeln prüfen, ob die konkrete Befristung wirksam vereinbart wurde.":"اگر یک تاریخ پایان معتبر توافق شده باشد، یک قرارداد مدت‌دار تقویمی اصولاً در همان تاریخ تمام می‌شود. § 15 TzBfG قاعده‌های بیشتری دارد. در یک مدت‌دار بودن هدفی به جای تاریخ یک هدف مشخص توافق شده است. برای یک فسخ عادی هم شرط‌های خاصی اعتبار دارند. در صورت شک بگذارید بررسی شود که آیا مدت‌دار بودن مشخص معتبر توافق شده است.","Probezeit nicht pauschal bewerten":"دورهٔ آزمایشی را کلی ارزیابی نکردن","Eine Verlängerung ändert die bisher vereinbarte Dauer. „Vielleicht länger“ ist noch keine bestätigte Verlängerung. Für die Probezeit enthält § 622 BGB eine besondere Kündigungsregel. Sie gilt nur in einem begrenzten Zeitraum. Tarifverträge können abweichen. Bei befristeten Stellen muss die Probezeit zu Dauer und Tätigkeit passen. Das regelt § 15 TzBfG.":"یک تمدید مدت توافق‌شدهٔ تا حالا را تغییر می‌دهد. «شاید طولانی‌تر» هنوز یک تمدید تأییدشده نیست. برای دورهٔ آزمایشی § 622 BGB یک قاعدهٔ خاص فسخ دارد. این قاعده فقط در یک دورهٔ محدود اعتبار دارد. قراردادهای جمعی ممکن است فرق کنند. در کارهای مدت‌دار دورهٔ آزمایشی باید با مدت و کار جور باشد. این را § 15 TzBfG تنظیم می‌کند.","Konkrete Wirkung prüfen lassen":"گذاشتن اینکه اثر مشخص بررسی شود","Trage Enddatum, Probezeit und Kündigungsklausel getrennt in eine Übersicht ein. Frage bei widersprüchlichen Angaben nach und hole bei Wirksamkeitsfragen fachkundige Hilfe. Lass deine Kündigungsfrist anhand von Vertrag, Gesetz und möglichen Tarifregeln prüfen. Ein Übergang von einer Probephase zu weiterer Beschäftigung ist nicht dasselbe wie die Verlängerung einer Befristung.":"تاریخ پایان، دورهٔ آزمایشی و بند فسخ را جدا در یک جدول بنویسید. در معلومات متناقض بپرسید و در سوال‌های اعتبار کمک متخصص بگیرید. بگذارید مهلت فسخ شما بر اساس قرارداد، قانون و قاعده‌های احتمالی قرارداد جمعی بررسی شود. گذر از یک مرحلهٔ آزمایشی به ادامهٔ کار همان تمدید یک قرارداد مدت‌دار نیست.","Zeitbegriffe einsetzen":"گذاشتن مفهوم‌های وقت","Setze „Befristung“ und „Probezeit“ ein.":"„Befristung“ (مدت‌دار بودن) و „Probezeit“ (دورهٔ آزمایشی) را بگذارید.","Beide Zeitangaben können im selben Vertrag vorkommen.":"هر دو معلومات وقت ممکن است در یک قرارداد بیایند.","Ihre Zwecke und möglichen Folgen sind nicht identisch.":"هدف‌ها و نتیجه‌های احتمالی آن‌ها یکسان نیستند.","Vereinbarte zeitliche Begrenzung: ___.":"Vereinbarte zeitliche Begrenzung: ___. (محدودیت زمانی توافق‌شده: ___.)","Anfängliche Erprobungsphase: ___.":"Anfängliche Erprobungsphase: ___. (مرحلهٔ آزمایشی اول: ___.)","Angaben zuordnen":"وصل کردن معلومات","Verbinde den Eintrag mit dem Prüffeld.":"نوشته را به خانهٔ بررسی وصل کنید.","Lies die Felder getrennt und anschließend im Zusammenhang.":"خانه‌ها را جدا و بعد در پیوند با هم بخوانید.","Die Übersicht verhindert eine voreilige Gleichsetzung.":"این جدول از یکی دانستن عجولانه جلوگیری می‌کند.","Enddatum":"تاریخ پایان","anfängliche Erprobung":"آزمایش اول","Frist und Verfahren":"مهلت و روند","Die unbestätigte Aussicht hören":"شنیدن چشم‌انداز تأییدنشده","Welches Wort zeigt, dass die Verlängerung noch nicht feststeht?":"کدام کلمه نشان می‌دهد که تمدید هنوز قطعی نیست؟","Gesucht ist das einschränkende Wort.":"کلمهٔ محدودکننده پرسیده شده است.","„Vielleicht“ kennzeichnet eine Möglichkeit und keine Zusage.":"„Vielleicht“ (شاید) یک امکان را نشان می‌دهد و وعده نیست.","Eine Vertragsübersicht beschreiben":"توصیف یک جدول قرارداد","Schreibe drei Sätze über getrennte Zeitangaben und eine offene Verlängerung.":"سه جمله دربارهٔ معلومات وقت جداگانه و یک تمدید باز بنویسید.","Beschreibe den Befund statt die Wirksamkeit selbst zu entscheiden.":"یافته را توصیف کنید، به جای اینکه خودتان دربارهٔ اعتبار تصمیم بگیرید.","Die Übersicht benennt die richtige Unterscheidung und offene Vereinbarung.":"این جدول جدایی درست و توافق باز را نام می‌برد.","Trennst du Probezeit und Befristungsende?":"آیا دورهٔ آزمایشی و پایان قرارداد مدت‌دار را جدا می‌کنید؟","Vermeidest du eine automatische Gleichsetzung beider Daten?":"آیا از یکی دانستن خودکار هر دو تاریخ پرهیز می‌کنید؟","Bleibt die Verlängerung unbestätigt?":"آیا تمدید تأییدنشده می‌ماند؟","Verzichtest du auf eine ungeprüfte persönliche Fristberechnung?":"آیا از یک حساب بررسی‌نشدهٔ شخصی مهلت صرف‌نظر می‌کنید؟","Ende eines befristeten Vertrags":"پایان یک قرارداد مدت‌دار","Eine Probezeit und ein Befristungsende betreffen unterschiedliche Regelungen.":"یک دورهٔ آزمایشی و یک پایان مدت‌دار به قاعده‌های مختلف مربوط‌اند.","Die Wirksamkeit einer Befristung folgt nicht allein aus ihrer Überschrift.":"اعتبار یک مدت‌دار بودن فقط از عنوانش نتیجه نمی‌شود.","Ende befristeter Arbeitsverträge":"پایان قراردادهای کار مدت‌دار","Kündigungsfristen und Probezeit":"مهلت‌های فسخ و دورهٔ آزمایشی","Bei einer Kündigung zeitnah Hilfe suchen":"در یک فسخ زود کمک خواستن","Du sicherst die Unterlagen und erkennst, dass kurze Fristen sofortige Klärung erfordern können.":"شما اسناد را محفوظ می‌کنید و می‌فهمید که مهلت‌های کوتاه ممکن است روشن‌سازی فوری بخواهند.","Internes Gespräch als Friststopp behandeln":"گفتگوی داخلی را توقف مهلت دانستن","Falsch: „Solange die Chefin nicht antwortet, läuft keine Frist.“ Richtig: Rechtliche Fristen sofort unabhängig vom internen Gespräch klären.":"اشتباه: «تا وقتی رئیس جواب نداده، هیچ مهلتی جریان ندارد.» درست: مهلت‌های حقوقی را فوراً و بدون ربط با گفتگوی داخلی روشن کنید.","Briefdatum mit Zugang gleichsetzen":"یکی دانستن تاریخ نامه با رسیدن آن","Falsch: Ohne Prüfung ausschließlich das Datum oben auf dem Schreiben verwenden. Richtig: Tatsächlichen Zugang dokumentieren und die Frist fachkundig prüfen lassen.":"اشتباه: بدون بررسی فقط تاریخ بالای نامه را به کار ببرید. درست: رسیدن واقعی را ثبت کنید و بگذارید مهلت توسط متخصص بررسی شود.","Was sollte Jelena sofort festhalten?":"یلنا باید فوراً چه چیزی را ثبت کند؟","Nur das Datum oben auf dem Schreiben.":"فقط تاریخ بالای نامه.","Den tatsächlichen Zugang des Schreibens.":"رسیدن واقعی نامه.","Nur den später vereinbarten Gesprächstermin.":"فقط وقت گفتگوی بعداً توافق‌شده.","Der Zugang ist ein wesentlicher Bezugspunkt für die Fristprüfung.":"رسیدن (Zugang) یک نقطهٔ مهم برای بررسی مهلت است.","Was ist beim Warten auf die Chefin zu beachten?":"در انتظار رئیس به چه چیزی باید توجه کرد؟","Interne Gespräche ersetzen die fristgerechte rechtliche Reaktion nicht automatisch.":"گفتگوهای داخلی خودکار جای واکنش حقوقی به‌موقع را نمی‌گیرند.","Die interne Beschwerde wahrt allein bereits jede Klagefrist.":"شکایت داخلی به تنهایی هر مهلت دعوا را حفظ می‌کند.","Die Frist beginnt erst nach der Antwort auf die interne Beschwerde.":"مهلت فقط بعد از جواب به شکایت داخلی شروع می‌شود.","Eine ausstehende Antwort ist kein verlässlicher Grund, die Fristklärung aufzuschieben.":"یک جواب هنوز نیامده دلیل قابل اعتمادی برای عقب انداختن روشن‌سازی مهلت نیست.","Welche allgemeine Klagefrist nennt § 4 KSchG?":"§ 4 KSchG کدام مهلت عمومی دعوا را نام می‌برد؟","Drei Wochen erst nach dem internen Klärungsgespräch.":"سه هفته فقط بعد از گفتگوی روشن‌سازی داخلی.","Einen Monat nach dem Datum auf dem Schreiben.":"یک ماه بعد از تاریخ نامه.","Grundsätzlich drei Wochen nach Zugang der schriftlichen Kündigung.":"اصولاً سه هفته بعد از رسیدن فسخ نوشتاری.","Die Regel ist kurz; mögliche Besonderheiten werden sofort konkret geprüft.":"این قاعده کوتاه است؛ خصوصیت‌های احتمالی فوراً و مشخص بررسی می‌شوند.","Notiere beim Zugang eines Schreibens den tatsächlichen Empfang und suche ohne Abwarten fachkundige Unterstützung.":"در رسیدن یک نامه دریافت واقعی را یادداشت کنید و بدون انتظار حمایت متخصص بخواهید.","Ein Schreiben ernst nehmen":"جدی گرفتن یک نامه","Jelena: „Ich habe heute eine schriftliche Kündigung erhalten und verstehe sie nicht.“ Freundin: „Bewahre das Schreiben auf und notiere, wann du es bekommen hast.“ Jelena: „Soll ich erst auf die Antwort meiner Chefin warten?“ Freundin: „Warte mit rechtlicher Beratung nicht darauf. Für eine Klage können kurze Fristen laufen.“":"یلنا: «امروز یک فسخ نوشتاری گرفته‌ام و آن را نمی‌فهمم.» دوستش: «نامه را نگه دار و یادداشت کن که چه وقت آن را گرفتی.» یلنا: «اول منتظر جواب رئیسم بمانم؟» دوستش: «برای مشورهٔ حقوقی منتظر آن نمان. برای یک دعوا ممکن است مهلت‌های کوتاه جریان داشته باشند.»","Fristen nicht mit Gesprächen verwechseln":"مهلت‌ها را با گفتگوها اشتباه نکردن","§ 4 KSchG nennt grundsätzlich drei Wochen nach Zugang der schriftlichen Kündigung für eine Klage gegen ihre Wirksamkeit. Lass Besonderheiten sofort prüfen. Eine interne Beschwerde ersetzt die Klage nicht automatisch. Auch ein Gespräch stoppt die Frist nicht einfach. Kläre deshalb umgehend den Empfangstag und die nötige rechtliche Handlung.":"§ 4 KSchG اصولاً سه هفته بعد از رسیدن فسخ نوشتاری را برای یک دعوا علیه اعتبار آن نام می‌برد. بگذارید خصوصیت‌ها فوراً بررسی شوند. یک شکایت داخلی خودکار جای دعوا را نمی‌گیرد. یک گفتگو هم مهلت را همین طوری متوقف نمی‌کند. به همین دلیل روز دریافت و کار حقوقی لازم را فوراً روشن کنید.","Wichtige Unterlagen zusammenstellen":"جمع کردن اسناد مهم","Sichere die Kündigung, den Vertrag und wichtige Nachrichten. Bewahre auch den Umschlag auf, wenn er noch da ist. Zugang bedeutet hier: Wann hast du das Schreiben tatsächlich erhalten? Dieses Datum kann vom Briefdatum abweichen. Notiere es genau. Lass die Frist prüfen, statt nur einen Monat ab dem Briefdatum zu rechnen.":"فسخ، قرارداد و پیام‌های مهم را محفوظ کنید. پاکت را هم نگه دارید، اگر هنوز هست. رسیدن (Zugang) اینجا یعنی: نامه را واقعاً چه وقت گرفتید؟ این تاریخ ممکن است با تاریخ نامه فرق کند. آن را دقیق یادداشت کنید. بگذارید مهلت بررسی شود، به جای اینکه فقط یک ماه از تاریخ نامه حساب کنید.","Die passende Unterstützung erreichen":"رسیدن به حمایت مناسب","Suche sofort Hilfe, etwa bei einer arbeitsrechtlichen Beratung oder deiner zuständigen Gewerkschaft. Auch die Rechtsantragstelle des Arbeitsgerichts ist eine Anlaufstelle. Frage, welche Hilfe du dort bekommst und welche Unterlagen du brauchst. Unterschreibe unter Zeitdruck keinen Aufhebungsvertrag oder Verzicht. Lass die Folgen vorher prüfen.":"فوراً کمک بخواهید، مثلاً در یک مشورهٔ حقوق کار یا اتحادیهٔ کارگری مسئول شما. بخش درخواست حقوقی دادگاه کار (Rechtsantragstelle) هم یک جای مراجعه است. بپرسید آنجا چه کمکی می‌گیرید و کدام اسناد لازم دارید. زیر فشار وقت هیچ قرارداد فسخ توافقی (Aufhebungsvertrag) یا صرف‌نظری را امضا نکنید. بگذارید نتیجه‌ها پیش از آن بررسی شوند.","Beratungsbegriffe ergänzen":"کامل کردن مفهوم‌های مشوره","Setze „Zugang“ und „Frist“ ein.":"„Zugang“ (رسیدن) و „Frist“ (مهلت) را بگذارید.","Beide Begriffe sind für die zeitnahe Prüfung wichtig.":"هر دو مفهوم برای بررسی زود مهم‌اند.","Der Empfangszeitpunkt kann den Beginn einer Frist bestimmen.":"وقت دریافت ممکن است شروع یک مهلت را تعیین کند.","Der tatsächliche Empfang heißt auch ___.":"Der tatsächliche Empfang heißt auch ___. (دریافت واقعی ___ هم نامیده می‌شود.)","Die zeitliche Grenze für eine Handlung heißt ___.":"Die zeitliche Grenze für eine Handlung heißt ___. (مرز زمانی برای یک کار ___ نامیده می‌شود.)","Unterlagen sinnvoll zuordnen":"وصل کردن معقول اسناد","Verbinde Angabe und Zweck.":"معلومات و هدف را وصل کنید.","Sicherung und fachkundige Reaktion ergänzen sich.":"محفوظ کردن و واکنش متخصص همدیگر را کامل می‌کنند.","Die Schritte vermeiden ein folgenloses bloßes Abwarten.":"این قدم‌ها از یک انتظار بی‌نتیجه جلوگیری می‌کنند.","Empfangstag notieren":"یادداشت روز دریافت","Schreiben aufbewahren":"نگه داشتن نامه","zeitnah Beratung suchen":"زود مشوره خواستن","Den Empfangszeitpunkt hören":"شنیدن وقت دریافت","Wann hat Jelena das Schreiben tatsächlich erhalten? Antworte mit einem Zeitwort.":"یلنا نامه را واقعاً چه وقت گرفت؟ با یک کلمهٔ زمانی (به آلمانی) جواب دهید.","Gesucht ist der tatsächliche Empfang.":"دریافت واقعی پرسیده شده است.","Der Zugang erfolgte nach Jelenas Angabe heute.":"به گفتهٔ یلنا رسیدن امروز (heute) بود.","Eine Beratungsanfrage verfassen":"نوشتن یک درخواست مشوره","Schreibe drei Sätze: schriftliche Kündigung heute erhalten, Unterlagen vorhanden, sofortige Fristprüfung erbeten.":"سه جمله بنویسید: فسخ نوشتاری امروز رسید، اسناد موجود است، بررسی فوری مهلت خواسته می‌شود.","Behandle den Zugang als zeitkritische Angabe und frage nach dem weiteren Weg.":"رسیدن را یک معلومات حساس به وقت بدانید و دربارهٔ راه بعدی بپرسید.","Die Anfrage unterstützt eine umgehende Prüfung statt einer ungesicherten Fristberechnung.":"این درخواست یک بررسی فوری را حمایت می‌کند، به جای یک حساب نامطمئن مهلت.","Ist der tatsächliche Zugang als heute genannt?":"آیا رسیدن واقعی امروز نام برده شده است؟","Nennst du die verfügbaren Unterlagen?":"آیا اسناد موجود را نام می‌برید؟","Bittest du ausdrücklich um rasche Fristklärung?":"آیا صریحاً روشن‌سازی سریع مهلت را می‌خواهید؟","Vermeidest du eine eigene Aussage zur Wirksamkeit?":"آیا از یک گفتهٔ خودتان دربارهٔ اعتبار پرهیز می‌کنید؟","Klagefrist bei Kündigung":"مهلت دعوا در فسخ","Kurze Klagefristen verlangen zügige fachkundige Klärung.":"مهلت‌های کوتاه دعوا روشن‌سازی سریع متخصص می‌خواهند.","Ein interner Austausch ersetzt eine erforderliche gerichtliche Handlung nicht automatisch.":"یک گفتگوی داخلی خودکار جای یک کار لازم دادگاهی را نمی‌گیرد.","Eine arbeitsrechtliche Frage geordnet vorbereiten":"آماده کردن مرتب یک سوال حقوق کار","Du trennst Dokumentenwortlaut, tatsächlichen Ablauf und konkrete Beratungsfrage.":"شما متن سند، روند واقعی و سوال مشخص مشوره را جدا می‌کنید.","Bewertung als belegten Sachverhalt ausgeben":"ارزیابی را واقعیت ثابت‌شده جلوه دادن","Falsch: „Es ist sicher rechtswidrig“, ohne Zeiten und Regeln zu prüfen. Richtig: Tatsächlichen Ablauf schildern und die rechtliche Bewertung klären lassen.":"اشتباه: «حتماً غیرقانونی است»، بدون اینکه وقت‌ها و قاعده‌ها را بررسی کنید. درست: روند واقعی را تعریف کنید و بگذارید ارزیابی حقوقی روشن شود.","Zeitnachweise nachträglich passend machen":"بعداً جور کردن ثبت‌های وقت","Falsch: Aufzeichnungen verändern, damit sie zum gewünschten Ergebnis passen. Richtig: Tatsächliche Angaben und vorhandene Belege unverändert sichern.":"اشتباه: ثبت‌ها را تغییر دهید تا با نتیجهٔ دلخواه جور شوند. درست: معلومات واقعی و مدرک‌های موجود را بدون تغییر محفوظ کنید.","Welche Unterlagen helfen im Beispiel zuerst?":"در مثال کدام اسناد اول کمک می‌کنند؟","Nur die letzte Kontobewegung ohne Arbeitszeitaufzeichnung.":"فقط آخرین حرکت حساب بدون ثبت ساعت کار.","Nur einen allgemeinen Stundenplan ohne tatsächliche Zeiten.":"فقط یک برنامهٔ عمومی ساعت‌ها بدون وقت‌های واقعی.","Zeitaufzeichnungen, Vertrag und Abrechnung.":"ثبت‌های وقت، قرارداد و صورت‌حساب.","Diese Unterlagen verbinden tatsächliche Arbeit, Vereinbarung und Zahlung.":"این اسناد کار واقعی، توافق و پرداخت را وصل می‌کنند.","Welche Frage ist sachlich vorbereitet?":"کدام سوال از نظر محتوا آماده است؟","Kann ich aus längerer Anwesenheit allein schon einen festen Zahlungsanspruch ableiten?":"آیا می‌توانم فقط از حضور طولانی‌تر یک حق قطعی پرداخت نتیجه بگیرم؟","Wie sind die dokumentierten zusätzlichen Zeiten nach den geltenden Regeln zu behandeln?":"وقت‌های اضافی ثبت‌شده بر اساس قاعده‌های معتبر چطور باید رسیدگی شوند؟","Genügt der Monatsgesamtbetrag ohne Prüfung der vereinbarten Regeln?":"آیا مبلغ کل ماه بدون بررسی قاعده‌های توافق‌شده کافی است؟","Die Frage knüpft an Tatsachen an und lässt die rechtliche Bewertung offen.":"این سوال به واقعیت‌ها وصل است و ارزیابی حقوقی را باز می‌گذارد.","Was sollte frühzeitig geklärt werden?":"چه چیزی باید زود روشن شود؟","Mögliche Fristen und zuständige Hilfe.":"مهلت‌های احتمالی و کمک مسئول.","Nur ob die Nachricht an den Betrieb bereits gelesen wurde.":"فقط اینکه آیا پیام به شرکت از قبل خوانده شده.","Nur die Formulierung der nächsten Rückfrage ohne zeitliche Prüfung.":"فقط نوشتن سوال بعدی بدون بررسی زمانی.","Fristen können die nötige Reaktion bestimmen und dürfen nicht ungeprüft verstreichen.":"مهلت‌ها ممکن است واکنش لازم را تعیین کنند و نباید بررسی‌نشده بگذرند.","Bringe eine kurze Zeitleiste und die zugehörigen Unterlagen mit, statt nur ein pauschales Urteil über den Betrieb.":"یک خط زمانی کوتاه و اسناد مربوط را بیاورید، نه فقط یک قضاوت کلی دربارهٔ شرکت.","Eine unklare Mehrarbeit schildern":"تعریف یک اضافه‌کاری نامشخص","Tina: „Ich habe an drei Tagen länger gearbeitet. In der Abrechnung finde ich dazu keine klare Position.“ Beratungsstelle: „Welche Zeiten und Vereinbarungen liegen vor?“ Tina: „Ich habe meine tatsächlichen Zeiten und den Vertrag.“ Beratungsstelle: „Dann ordnen wir die Unterlagen. Ob und wie ein Anspruch besteht, prüfen wir anhand der konkreten Regeln.“":"تینا: «در سه روز بیشتر کار کرده‌ام. در صورت‌حساب هیچ بخش روشنی برای آن پیدا نمی‌کنم.» دفتر مشوره: «کدام وقت‌ها و توافق‌ها موجود است؟» تینا: «وقت‌های واقعی‌ام و قرارداد را دارم.» دفتر مشوره: «پس اسناد را مرتب می‌کنیم. اینکه آیا و چطور یک حق وجود دارد، بر اساس قاعده‌های مشخص بررسی می‌کنیم.»","Fakten und Bewertung trennen":"جدا کردن واقعیت‌ها و ارزیابی","Beschreibe, was an welchem Tag passiert ist. Nenne passende Belege. „An drei Tagen länger gearbeitet“ ist ein konkreter Anfang. „Der Betrieb handelt immer illegal“ ist schon ein Urteil. Für die Beratung sind genaue Zeiten und Vereinbarungen hilfreicher. Ob daraus ein Anspruch folgt, muss anhand deines Falls geprüft werden.":"توصیف کنید که در کدام روز چه اتفاقی افتاد. مدرک‌های مناسب را نام ببرید. „An drei Tagen länger gearbeitet“ (در سه روز بیشتر کار کرده) یک شروع مشخص است. „Der Betrieb handelt immer illegal“ (شرکت همیشه غیرقانونی عمل می‌کند) از همین حالا یک قضاوت است. برای مشوره وقت‌ها و توافق‌های دقیق مفیدترند. اینکه آیا از آن یک حق نتیجه می‌شود، باید بر اساس مورد شما بررسی شود.","Die Frage und Unterlagen zuordnen":"وصل کردن سوال و اسناد","Erstelle eine kurze Zeitleiste: Was ist an welchem Tag passiert? Ordne jedem Punkt einen vorhandenen Beleg zu. Dazu können Vertrag, Abrechnung und Nachrichten gehören. Notiere auch deine bisherigen Rückfragen. Verändere keine Zeitnachweise nachträglich. Sammle für deine Frage keine fremden Personaldaten, die dafür nicht nötig sind.":"یک خط زمانی کوتاه بسازید: در کدام روز چه اتفاقی افتاد؟ به هر نکته یک مدرک موجود وصل کنید. قرارداد، صورت‌حساب و پیام‌ها ممکن است جزو آن باشند. سوال‌های تا حالای خود را هم یادداشت کنید. هیچ ثبت وقت را بعداً تغییر ندهید. برای سوال خود هیچ دادهٔ کارمندی دیگران را که لازم نیست جمع نکنید.","Früh handeln und Grenzen der Hilfe klären":"زود عمل کردن و روشن کردن حد کمک","Frage früh, welche Fristen gelten und wer dir helfen kann. Ein Betriebsrat oder eine Gewerkschaft kann je nach Fall unterstützen. Kläre, wann du eine Rechtsberatung oder das Gericht brauchst. Eine allgemeine Kursantwort wahrt keine persönliche Frist. Notiere deshalb den nächsten vereinbarten Schritt und bis wann du ihn erledigen musst.":"زود بپرسید کدام مهلت‌ها اعتبار دارند و چه کسی می‌تواند به شما کمک کند. یک شورای کارکنان (Betriebsrat) یا یک اتحادیهٔ کارگری بسته به مورد می‌تواند حمایت کند. روشن کنید که چه وقت یک مشورهٔ حقوقی یا دادگاه لازم دارید. یک جواب عمومی کورس هیچ مهلت شخصی را حفظ نمی‌کند. به همین دلیل قدم بعدی توافق‌شده و اینکه تا چه وقت باید آن را انجام دهید یادداشت کنید.","Die Vorbereitung ergänzen":"کامل کردن آمادگی","Setze „Zeiten“ und „Vertrag“ ein.":"„Zeiten“ (وقت‌ها) و „Vertrag“ (قرارداد) را بگذارید.","Tatsachen und Vereinbarung liefern verschiedene Informationen.":"واقعیت‌ها و توافق معلومات مختلفی می‌دهند.","Erst ihr Vergleich ermöglicht eine konkrete Frage.":"فقط مقایسهٔ آن‌ها یک سوال مشخص را ممکن می‌کند.","Tina sichert ihre tatsächlichen ___.":"Tina sichert ihre tatsächlichen ___. (تینا ___ واقعی خود را محفوظ می‌کند.)","Die vereinbarten Bedingungen stehen im ___.":"Die vereinbarten Bedingungen stehen im ___. (شرط‌های توافق‌شده در ___ نوشته شده‌اند.)","Belege ihrer Rolle zuordnen":"وصل کردن مدرک‌ها به نقششان","Verbinde Unterlage und Zweck.":"سند و هدف را وصل کنید.","Kein einzelnes Dokument erklärt zwingend den gesamten Fall.":"هیچ سند تنها لزوماً تمام مورد را توضیح نمی‌دهد.","Die Unterlagen ergänzen sich bei der Beratung.":"این اسناد در مشوره همدیگر را کامل می‌کنند.","Zeitaufzeichnung":"ثبت وقت","Vertrag":"قرارداد","Abrechnung":"صورت‌حساب","Die Zahl der betroffenen Tage hören":"شنیدن تعداد روزهای مربوط","An wie vielen Tagen hat Tina länger gearbeitet? Schreibe eine Ziffer.":"تینا در چند روز بیشتر کار کرده است؟ یک رقم بنویسید.","Gefragt ist die Zahl der Tage, nicht eine berechnete Vergütung.":"تعداد روزها پرسیده شده، نه یک مزد حساب‌شده.","Tina nennt drei konkret dokumentierte Tage.":"تینا سه روز مشخصاً ثبت‌شده را نام می‌برد.","Eine geordnete Frage vorbereiten":"آماده کردن یک سوال مرتب","Schreibe vier Sätze: drei Tage Mehrarbeit, Abrechnung unklar, Belege vorhanden, Frage nach Regeln und Fristen.":"چهار جمله بنویسید: سه روز اضافه‌کاری، صورت‌حساب نامشخص، مدرک‌ها موجود، سوال دربارهٔ قاعده‌ها و مهلت‌ها.","Formuliere die Frage offen und bewahre die Originalbelege.":"سوال را باز بنویسید و مدرک‌های اصلی را نگه دارید.","Die Notiz bereitet eine individuelle Prüfung vor, statt deren Ergebnis vorwegzunehmen.":"این یادداشت یک بررسی فردی را آماده می‌کند، به جای اینکه نتیجهٔ آن را پیشاپیش بگوید.","Nennst du den konkreten tatsächlichen Ablauf?":"آیا روند واقعی مشخص را نام می‌برید؟","Beschreibst du die unklare Abrechnungsposition ohne Vorverurteilung?":"آیا بخش نامشخص صورت‌حساب را بدون پیش‌داوری توصیف می‌کنید؟","Ordnet dein Text die vorhandenen Belege zu?":"آیا متن شما مدرک‌های موجود را وصل می‌کند؟","Fragst du nach rechtlicher Einordnung und Fristen?":"آیا دربارهٔ جا دادن حقوقی و مهلت‌ها می‌پرسید؟","BMAS: Arbeitsrecht und wichtige Regeln":"BMAS: حقوق کار و قاعده‌های مهم","Eine Beratung beginnt mit konkreten Tatsachen und Unterlagen.":"یک مشوره با واقعیت‌ها و اسناد مشخص شروع می‌شود.","Allgemeine Orientierung wahrt keine persönliche Frist automatisch.":"راهنمایی عمومی هیچ مهلت شخصی را خودکار حفظ نمی‌کند.","BMAS: Arbeitsrecht im Überblick":"BMAS: نگاه کلی به حقوق کار"};})(typeof window!=="undefined"?window:globalThis);
